package com.lianxibu.site.service.jobs;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
import com.lianxibu.site.config.JobsRuntimeConfiguration;
import com.lianxibu.site.config.OwnerAdHocQuestionRuntimeConfiguration;
import com.lianxibu.site.controller.jobs.JobsController;
import com.lianxibu.site.controller.jobs.OwnerAdHocQuestionController;
import com.lianxibu.site.service.identity.IdentityService;
import com.lianxibu.site.service.settings.SettingsJdbcStore;
import java.util.*;
import org.junit.jupiter.api.*;
import org.springframework.beans.factory.ObjectProvider;
import org.springframework.boot.test.context.runner.ApplicationContextRunner;
import org.springframework.test.web.servlet.MockMvc;
import org.springframework.test.web.servlet.setup.MockMvcBuilders;

/** Actual formal Jobs assembly and native intent writer; authentication is fictional. */
class OwnerAdHocIntentCancelHttpTest {
 OwnerAdHocQuestionReadTest f;IdentityService auth;
 OwnerAdHocQuestionReadTest fixture(){return new OwnerAdHocQuestionReadTest();}
 @BeforeEach void setup(){f=fixture();f.setup();auth=mock(IdentityService.class);when(auth.authenticate("fictional-session")).thenReturn(f.c.owner);when(auth.authenticate("fictional-member")).thenReturn(new IdentityService.Actor("fictional-member","member"));when(auth.authorizeWrite("fictional-session","fictional-csrf","https://site.example.invalid")).thenReturn(f.c.owner);}
 @AfterEach void close(){f.restoreFixtureTimezone();}
 ApplicationContextRunner context(){return new ApplicationContextRunner().withUserConfiguration(JobsRuntimeConfiguration.class,OwnerAdHocQuestionRuntimeConfiguration.class).withBean(javax.sql.DataSource.class,()->f.c.f.source).withBean(org.springframework.transaction.PlatformTransactionManager.class,()->f.tx).withBean(SettingsJdbcStore.class,()->mock(SettingsJdbcStore.class)).withPropertyValues("site.browser.enabled=true","site.content.enabled=true","site.execution.enabled=true","site.execution.ad-hoc.enabled=false");}
 @SuppressWarnings("unchecked") MockMvc mvc(org.springframework.context.ApplicationContext c){ObjectProvider<IdentityService> identity=mock(ObjectProvider.class);when(identity.getIfAvailable()).thenReturn(auth);return MockMvcBuilders.standaloneSetup(new JobsController(identity,c.getBeanProvider(JobsService.class)),new OwnerAdHocQuestionController(identity,c.getBeanProvider(OwnerAdHocQuestionReadService.class))).build();}
 String id(){return f.accepted.command().intentId();}
 String body(long revision){return "{\"expected_revision\":"+revision+",\"action\":\"cancel\",\"reason\":\"Fictional intent cancellation\"}";}
 org.springframework.test.web.servlet.request.MockHttpServletRequestBuilder request(String id,String body,String key){return post("/admin/jobs/{id}/actions",id).cookie(new jakarta.servlet.http.Cookie("lianxibu_session","fictional-session")).header("X-CSRF-Token","fictional-csrf").header("Origin","https://site.example.invalid").header("Idempotency-Key",key).contentType("application/json").content(body);}
 org.springframework.test.web.servlet.request.MockHttpServletRequestBuilder read(String path,String id){return get(path,id).cookie(new jakarta.servlet.http.Cookie("lianxibu_session","fictional-session"));}
 @Test void ActualFormalConsumerCancelsTheOriginalIntentAndReadsItsPreservedQuestion(){context().run(c->{assertNull(c.getStartupFailure());assertEquals(1,c.getBeansOfType(OwnerAdHocIntentCancelService.class).size());var api=mvc(c);var first=api.perform(request(id(),body(0),"fictional-http-cancel")).andExpect(status().isOk()).andExpect(header().string("Cache-Control","no-store")).andExpect(jsonPath("$.data.result_resource_ref.kind").value("job")).andExpect(jsonPath("$.data.result_resource_ref.id").value(id())).andExpect(jsonPath("$.data.result_revision").value(1)).andReturn().getResponse().getContentAsString();api.perform(read("/admin/jobs/{id}",id())).andExpect(status().isOk()).andExpect(jsonPath("$.data.state").value("cancelled")).andExpect(jsonPath("$.data.call_count").value(0));api.perform(read("/admin/jobs/{id}/ad-hoc",id())).andExpect(status().isOk()).andExpect(jsonPath("$.data.original_request.prompt").value(f.accepted.command().prompt())).andExpect(jsonPath("$.data.prepared_job").isEmpty());assertFalse(first.contains(f.accepted.command().prompt()));assertEquals(0,f.c.f.count("record_kind='logical_task' OR record_kind='ai_attempt'"));});}
 @Test void OriginalHttpReplayAndSameInputBudgetIdentitySurviveLaterState(){context().run(c->{var api=mvc(c);var first=api.perform(request(id(),body(0),"fictional-http-cancel")).andExpect(status().isOk()).andReturn().getResponse().getContentAsString();f.c.f.jdbc.update("UPDATE jobs SET revision=8,state='superseded' WHERE id=?",id());var replay=api.perform(request(id(),body(0),"fictional-http-cancel")).andExpect(status().isOk()).andReturn().getResponse().getContentAsString();var json=tools.jackson.databind.json.JsonMapper.shared();assertEquals(json.readTree(first).get("data"),json.readTree(replay).get("data"));api.perform(request(id(),body(1),"fictional-http-cancel")).andExpect(status().isConflict()).andExpect(jsonPath("$.error.code").value("identity_conflict"));assertEquals(1,f.c.f.count("target_type='job_intent_cancel'"));});}
 @Test void PreparedIntentRefusesAndExistingRootCancellationStillOwnsItsOriginalBudget(){context().run(c->{var api=mvc(c);var root=f.prepare();api.perform(request(id(),body(0),"fictional-intent-too-late")).andExpect(status().isConflict()).andExpect(jsonPath("$.error.code").value("run_frozen"));api.perform(request(root.ownerId(),body(0),"fictional-root-cancel")).andExpect(status().isOk()).andExpect(jsonPath("$.data.result_resource_ref.id").value(root.ownerId()));assertEquals(1,f.c.f.count("record_kind='logical_task' AND state='cancelled' AND call_count=0 AND max_attempts=3"));assertEquals(0,f.c.f.count("target_type='job_intent_cancel'"));});}
 @Test void NativeDamageAndClosedBodyProduceFixedErrorsWithoutLeakingOriginalQuestion(){context().run(c->{var api=mvc(c);api.perform(request(id(),body(0).replace("\"reason\":","\"attempt_id\":\"fictional-extra\",\"reason\":"),"fictional-extra-key")).andExpect(status().isBadRequest());api.perform(request("fictional-absent",body(0),"fictional-absent-key")).andExpect(status().isNotFound());f.c.f.jdbc.update("UPDATE jobs SET action_payload_hash=? WHERE target_type='owner_ad_hoc_create'",new byte[32]);var failure=api.perform(request(id(),body(0),"fictional-damaged-key")).andExpect(status().isServiceUnavailable()).andExpect(header().string("Retry-After","1")).andExpect(header().string("Cache-Control","no-store")).andExpect(jsonPath("$.error.code").value("temporarily_unavailable")).andReturn().getResponse().getContentAsString();assertFalse(failure.contains("SELECT"));assertFalse(failure.contains(f.accepted.command().prompt()));assertEquals(0,f.c.f.count("target_type='job_intent_cancel'"));});}
 @Test void OwnerAndCsrfAuthorizationPrecedeMalformedJsonAndBrokenSql(){context().run(c->{var api=mvc(c);f.c.f.jdbc.execute("DROP TABLE jobs");api.perform(post("/admin/jobs/fictional-id/actions").contentType("application/json").content("{")).andExpect(status().isUnauthorized());api.perform(post("/admin/jobs/{id}/actions",id()).cookie(new jakarta.servlet.http.Cookie("lianxibu_session","fictional-member")).contentType("application/json").content("{")).andExpect(status().isForbidden());when(auth.authorizeWrite("fictional-session","fictional-csrf","https://site.example.invalid")).thenThrow(new IdentityService.Rejected(IdentityService.Refusal.FORBIDDEN,null));api.perform(request(id(),"{","fictional-csrf-key")).andExpect(status().isForbidden());});}
 @Test void MandatoryFormalBeanHasZeroStartupIoAndEveryMissingFlagKeepsItAbsent(){var source=mock(javax.sql.DataSource.class);var manager=mock(org.springframework.transaction.PlatformTransactionManager.class);var settings=mock(SettingsJdbcStore.class);String[] flags={"site.browser.enabled","site.content.enabled","site.execution.enabled"};for(int omit=-1;omit<3;omit++){List<String> enabled=new ArrayList<>();for(int n=0;n<3;n++)if(n!=omit)enabled.add(flags[n]+"=true");new ApplicationContextRunner().withUserConfiguration(JobsRuntimeConfiguration.class).withBean(javax.sql.DataSource.class,()->source).withBean(org.springframework.transaction.PlatformTransactionManager.class,()->manager).withBean(SettingsJdbcStore.class,()->settings).withPropertyValues(enabled.toArray(String[]::new)).run(c->{assertNull(c.getStartupFailure());assertEquals(enabled.size()==3?1:0,c.getBeansOfType(OwnerAdHocIntentCancelService.class).size());});}verifyNoInteractions(source,manager,settings);}
}
